"""Indexed min heap implementation."""

from typing import Any, Dict, List, Optional, Tuple


class IndexedMinHeap:
    def __init__(self):
        self.heap: List[Tuple[float, str, Any]] = []  # (priority, item_id, payload)
        self.pos_map: Dict[str, int] = {}

    def push(self, item_id: str, priority: float, payload: Any = None) -> None:
        idx = len(self.heap)
        self.heap.append((priority, item_id, payload))
        self.pos_map[item_id] = idx
        self._sift_up(idx)

    def decrease_key(self, item_id: str, new_priority: float) -> bool:
        if item_id not in self.pos_map:
            return False
        idx = self.pos_map[item_id]
        curr_priority, _, payload = self.heap[idx]
        if new_priority >= curr_priority:
            return False
        self.heap[idx] = (new_priority, item_id, payload)
        self._sift_up(idx)
        return True

    def pop_min(self) -> Optional[Tuple[float, str, Any]]:
        if not self.heap:
            return None
        min_item = self.heap[0]
        del self.pos_map[min_item[1]]
        last_item = self.heap.pop()
        if self.heap:
            self.heap[0] = last_item
            self.pos_map[last_item[1]] = 0
            self._sift_down(0)
        return min_item

    def _sift_up(self, idx: int) -> None:
        while idx > 0:
            parent = (idx - 1) // 2
            if self.heap[idx][0] < self.heap[parent][0]:
                # Swap elements
                self.heap[idx], self.heap[parent] = self.heap[parent], self.heap[idx]
                # BUG: Fails to update pos_map during sift-up swaps, desynchronizing item positions!
                idx = parent
            else:
                break

    def _sift_down(self, idx: int) -> None:
        n = len(self.heap)
        while 2 * idx + 1 < n:
            left = 2 * idx + 1
            right = 2 * idx + 2
            smallest = left
            if right < n and self.heap[right][0] < self.heap[left][0]:
                smallest = right
            if self.heap[smallest][0] < self.heap[idx][0]:
                self.pos_map[self.heap[idx][1]] = smallest
                self.pos_map[self.heap[smallest][1]] = idx
                self.heap[idx], self.heap[smallest] = self.heap[smallest], self.heap[idx]
                idx = smallest
            else:
                break

repo_files.priority_queue.py:
"""Task priority scheduler wrapping indexed min-heap."""

from typing import Any, Optional
from heap import IndexedMinHeap


class TaskScheduler:
    def __init__(self):
        self.heap = IndexedMinHeap()

    def schedule_task(self, task_id: str, priority_score: float, task_name: str) -> None:
        self.heap.push(task_id, priority_score, task_name)

    def reprioritize(self, task_id: str, higher_urgency_score: float) -> bool:
        return self.heap.decrease_key(task_id, higher_urgency_score)

    def pop_next_task(self) -> Optional[tuple[str, str]]:
        res = self.heap.pop_min()
        if res:
            _, task_id, task_name = res
            return task_id, task_name
        return None

